function initAudio(){if(ac){ac.resume();return;}try{ac=new (window.AudioContext||window.webkitAudioContext)();master=ac.createGain();master.gain.value=volume*.6;master.connect(ac.destination);noiseBuffer=ac.createBuffer(1,ac.sampleRate*.3,ac.sampleRate);let a=noiseBuffer.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;}catch{}}
function sound(kind,x=player.x,z=player.z,type=weapon){if(!ac||ac.state!=='running')return;const t=ac.currentTime,dist=Math.hypot(x-player.x,z-player.z),level=Math.max(.02,1/(1+dist*.06));let gain=ac.createGain();gain.connect(master);let panner;if(ac.createStereoPanner){panner=ac.createStereoPanner();panner.pan.value=Math.max(-1,Math.min(1,((x-player.x)*Math.cos(yaw)-(z-player.z)*Math.sin(yaw))/Math.max(10,dist)));panner.connect(gain);}const target=panner||gain;if(kind==='shot'||kind==='step'||kind==='hit'){const n=ac.createBufferSource();n.buffer=noiseBuffer;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=kind==='step'?450:kind==='hit'?1600:2800;n.connect(f);f.connect(target);gain.gain.setValueAtTime(level*(kind==='shot'?.5:kind==='hit'?.12:.055),t);gain.gain.exponentialRampToValueAtTime(.001,t+(kind==='shot'?.18:.075));n.start(t);n.stop(t+.2);}if(kind!=='step'){const osc=ac.createOscillator();osc.type=kind==='shot'?'triangle':'sine';osc.frequency.setValueAtTime(kind==='shot'?W[type].sound:kind==='loot'?700:kind==='hit'?1100:kind==='reload'?220:kind==='win'?660:180,t);osc.frequency.exponentialRampToValueAtTime(kind==='loot'?1200:kind==='win'?990:50,t+.16);const g=ac.createGain();g.gain.setValueAtTime(level*.12,t);g.gain.exponentialRampToValueAtTime(.001,t+.22);osc.connect(g);g.connect(target);osc.start(t);osc.stop(t+.23);}setTimeout(()=>{gain.disconnect();panner?.disconnect();},500);}
