function isBlocked(x,z,r=.4,y=0,h=1.7){if(Math.hypot(x,z)>102)return true;return bounds.some(({box:b})=>b.max.y>y+.38&&b.min.y<y+h&&x+r>b.min.x&&x-r<b.max.x&&z+r>b.min.z&&z-r<b.max.z);}
