function moveActor(a,dx,dz,r=.38){let moved=false,baseY=a.y||0;if(!isBlocked(a.x+dx,a.z,r,baseY)){a.x+=dx;moved=true;}if(!isBlocked(a.x,a.z+dz,r,baseY)){a.z+=dz;moved=true;}const g=groundAt(a.x,baseY,a.z);if(g>baseY&&g-baseY<=.4)a.y=g;return moved;}
