function makeBot(id,pos){const weapon=id%4===0?'sniper':'rifle',model=createOperative(id,weapon),{group,meshes,alertMesh}=model;dynamic.add(group);const bot={id,name:names[id],x:pos.x,y:pos.y||0,z:pos.z,hp:100,armor:0,alive:true,yaw:0,visualYaw:0,weapon,model,group,meshes,alertMesh,animate:model.animate,lastX:pos.x,lastZ:pos.z,walk:0,aimPitch:0};group.position.set(bot.x,bot.y,bot.z);group.rotation.y=Math.PI;model.animate(0,{time:0});return bot;}
