function startMatch(){$('storm-fx').style.opacity=0;camera.fov=76;camera.updateProjectionMatrix();show('scope',false);show('reload-progress',false);initAudio();clearDynamic();matchSeed=Date.now()>>>0;rng=seeded(matchSeed);elapsed=0;killCount=0;totalDamage=0;zoneStage=-1;stormTick=0;feed=[];$('feed').innerHTML='';player={x:-10,y:115,z:83,vx:0,vy:-8,vz:0,hp:100,armor:50,alive:true};yaw=Math.PI*.02;pitch=-.32;parachute=false;weapon='pistol';inventory={pistol:{ammo:15,reserve:75},rifle:null,sniper:null};meds=2;cooldown=0;reloading=0;healing=0;recoil=0;nearest=null;mapExpanded=false;$('map-wrap').classList.remove('expanded');keys={};mouseDown=false;aim=false;flash=0;state='deploy';grounded=false;zone={x:0,z:0,radius:128,damage:3};loot=world.lootSpots.map((p,i)=>makeLoot(p,i));const spots=[...world.spawns].sort(()=>rng()-.5);bots=spots.slice(0,11).map((p,i)=>makeBot(i,p));brain=createBotBrain({bots,world:{isBlocked:(x,z,r)=>isBlocked(x,z,r,0),lineOfSight,move:(b,dx,dz)=>moveActor(b,dx,dz),spawns:world.spawns},random:rng,onShoot:botShoot,onEliminated:()=>{}});for(const id of ['menu','pause','result'])show(id,false);show('hud',true);show('deploy-info',true);show('crosshair',false);show('touch-controls',touch);stormWall.visible=ring.visible=true;gunGroup.visible=false;parachuteRig.visible=true;requestControl();banner('空降开始 · 选择你的落点');updateHud();}
