function updateEffects(dt){recoil=Math.max(0,recoil-dt*.45);muzzleTimer-=dt;hitTimer-=dt;$('hitmarker').style.opacity=hitTimer>0?1:0;flash=Math.max(0,flash-dt*1.2);$('damage-flash').style.opacity=flash;toastTimer-=dt;if(toastTimer<=0)$('toast').style.opacity=0;bannerTimer-=dt;if(bannerTimer<=0)show('phase-banner',false);for(let i=tracers.length-1;i>=0;i--){const p=tracers[i];p.time-=dt;if(p.time<=0){effects.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();tracers.splice(i,1);}else p.mesh.material.opacity=p.time/p.total;}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.time-=dt;p.v.y-=14*dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.x+=dt*7;p.mesh.rotation.z+=dt*9;if(p.time<=0){effects.remove(p.mesh);p.mesh.geometry.dispose();if(p.mesh.material!==gunMats.gold)p.mesh.material.dispose();particles.splice(i,1);}}for(const c of loot)if(!c.opened)c.glow.scale.y=.85+Math.sin(elapsed*2+c.x)*.13;}
function tick(now){requestAnimationFrame(tick);const time=now/1000,dt=Math.min(.04,Math.max(0,time-lastTime));lastTime=time;frame++;if(state==='menu'){let a=time*.018;camera.position.set(Math.sin(a)*135,82,Math.cos(a)*135);camera.lookAt(0,1,0);world.update(time,dt);}else if(state==='playing'||state==='deploy'){if(state==='playing'){elapsed+=dt;updateZone(dt);brain.update(dt,elapsed,player,zone);animateBots(dt);}updatePlayer(dt);cooldown=Math.max(0,cooldown-dt);if(reloading){reloading-=dt;$('reload-progress i').style.width=(1-reloading/reloadTotal)*100+'%';if(reloading<=0){reloading=0;let inv=inventory[weapon],n=Math.min(W[weapon].mag-inv.ammo,inv.reserve);inv.ammo+=n;inv.reserve-=n;show('reload-progress',false);updateHud();sound('reload');}}if(healing){healing-=dt;$('reload-progress i').style.width=(1-healing/reloadTotal)*100+'%';if(healing<=0){healing=0;meds--;player.hp=Math.min(100,player.hp+60);show('reload-progress',false);toast('生命恢复 +60');sound('loot');updateHud();}}else if(!reloading)show('reload-progress',false);updateEffects(dt);world.update(time,dt);if(frame%6===0)drawMap();if(frame%120===0&&feed.length){feed=feed.filter(f=>elapsed-f.time<12);$('feed').innerHTML=feed.map(f=>`<div class="feed-item">${f.text}</div>`).join('');}}if(state==='end'){animateBots(dt);updateEffects(dt);}renderer.render(scene,camera);}
