addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
addEventListener('keydown',e=>{if(['Space','Tab','KeyM'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(state==='paused')resume();else if(['playing','deploy'].includes(state))pauseGame();return;}keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyR')reload();if(e.code==='KeyQ')heal();if(e.code==='KeyM'){mapExpanded=!mapExpanded;$('map-wrap').classList.toggle('expanded',mapExpanded);}if(e.code==='Space'&&state==='playing'&&grounded){player.vy=7.3;grounded=false;}if(['Digit1','Digit2','Digit3'].includes(e.code)&&state==='playing')selectWeapon(Object.keys(W)[+e.code.slice(-1)-1]);});addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('mousedown',e=>{if(!['playing','deploy'].includes(state))return;initAudio();if(!locked&&!touch){dragLook={x:e.clientX,y:e.clientY};requestControl();}if(e.button===0){mouseDown=true;if(state==='playing')shoot();}if(e.button===2)aim=true;});addEventListener('mouseup',e=>{if(e.button===0){mouseDown=false;dragLook=null;}if(e.button===2)aim=false;});addEventListener('mousemove',e=>{if(!['playing','deploy'].includes(state))return;if(locked){yaw-=e.movementX*.002*sensitivity;pitch=Math.max(-1.3,Math.min(1.3,pitch-e.movementY*.002*sensitivity));}else if(dragLook){yaw-=(e.clientX-dragLook.x)*.003*sensitivity;pitch=Math.max(-1.3,Math.min(1.3,pitch-(e.clientY-dragLook.y)*.003*sensitivity));dragLook={x:e.clientX,y:e.clientY};}});document.addEventListener('pointerlockchange',()=>{let was=locked;locked=document.pointerLockElement===canvas;if(was&&!locked&&['playing','deploy'].includes(state))pauseGame();});canvas.addEventListener('wheel',e=>{if(state!=='playing')return;e.preventDefault();const types=Object.keys(W).filter(k=>inventory[k]),idx=types.indexOf(weapon);selectWeapon(types[(idx+(e.deltaY>0?1:types.length-1))%types.length]);},{passive:false});addEventListener('blur',()=>{if(['playing','deploy'].includes(state))pauseGame();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&['playing','deploy'].includes(state))pauseGame();});
if(touch){const stick=$('joystick');stick.onpointerdown=e=>{stick.setPointerCapture(e.pointerId);touchMove(e);};stick.onpointermove=e=>{if(stick.hasPointerCapture(e.pointerId))touchMove(e);};function touchMove(e){let r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/40,y=(e.clientY-r.top-r.height/2)/40,l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}touchStick.x=x;touchStick.y=y;stick.firstElementChild.style.transform=`translate(${x*34}px,${y*34}px)`;}stick.onpointerup=stick.onpointercancel=()=>{touchStick.x=touchStick.y=0;stick.firstElementChild.style.transform='';};let look=$('touch-look'),point=null;look.onpointerdown=e=>{look.setPointerCapture(e.pointerId);point={x:e.clientX,y:e.clientY};};look.onpointermove=e=>{if(!point||!look.hasPointerCapture(e.pointerId))return;yaw-=(e.clientX-point.x)*.004*sensitivity;pitch=Math.max(-1.3,Math.min(1.3,pitch-(e.clientY-point.y)*.004*sensitivity));point={x:e.clientX,y:e.clientY};};look.onpointerup=()=>point=null;$('touch-fire').onpointerdown=e=>{e.target.setPointerCapture(e.pointerId);mouseDown=true;shoot();};$('touch-fire').onpointerup=$('touch-fire').onpointercancel=()=>mouseDown=false;$('touch-aim').onclick=()=>aim=!aim;$('touch-jump').onclick=()=>{if(state==='playing'&&grounded){player.vy=7.3;grounded=false;}};$('touch-interact').onclick=interact;$('touch-reload').onclick=reload;$('touch-heal').onclick=heal;}
// Read-only diagnostic state and progressive WebMCP support, no hidden gameplay advantages.
function snapshot(){return{state,elapsed:Math.round(elapsed),player:{x:+player.x.toFixed(2),y:+player.y.toFixed(2),z:+player.z.toFixed(2),health:Math.ceil(player.hp),armor:Math.ceil(player.armor)},alive:bots.filter(b=>b.alive).length+(player.alive?1:0),aiOpponents:bots.filter(b=>b.alive).length,kills:killCount,weapon,ammo:inventory[weapon]?.ammo??0,reserve:inventory[weapon]?.reserve??0,meds,zone:{...zone},lootRemaining:loot.filter(l=>!l.opened).length,world:{buildings:12,colliders:world.colliders.length},renderer:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles}};}
window.sunfall={getState:snapshot};if(document.modelContext?.registerTool){for(const tool of[{name:'sunfall_read_match',title:'Read SUNFALL match',description:'Read this local solo match state, remaining AI opponents, player health and safe zone. Does not move, aim or play.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No inputs accepted');return snapshot();}},{name:'sunfall_pause_match',title:'Pause SUNFALL match',description:'Pause the active solo game and show its existing settings screen.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No inputs accepted');if(!['playing','deploy'].includes(state))throw new Error('No active match to pause');pauseGame();return snapshot();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
